from round_geometry import *
from vtk.util.numpy_support import numpy_to_vtk,vtk_to_numpy
n='ACA falcine branch right';parent='ACA A5 right';v,f,p,d=round_collar(121.,.9);w,g=mesh(parent);tissue='brain.cingulate-gyrus-and-sulcus-posterior-dorsal-part.right';q,h=mesh(tissue);sd=vtk.vtkImplicitPolyDataDistance();sd.SetInput(poly(q,h));rim=w[d['parentRim']];print('parentrim signed brain distance range',[min(sd.EvaluateFunction(x)for x in rim),max(sd.EvaluateFunction(x)for x in rim)],'centre',sd.EvaluateFunction(rim.mean(0)))
c=vtk.vtkCollisionDetectionFilter();c.SetInputData(0,poly(p,f));c.SetInputData(1,poly(q,h));tt=vtk.vtkTransform();c.SetTransform(0,tt);c.SetTransform(1,tt);c.SetCollisionModeToHalfContacts();c.SetCellTolerance(1e-7);c.Update();ci=vtk_to_numpy(c.GetContactCells(0));tri=p[f[np.unique(ci)]];print('newcollar contactbounds',tri.reshape(-1,3).min(0),tri.reshape(-1,3).max(0),'parentcentre',rim.mean(0));print('closestcontactfromparent',np.linalg.norm(tri.reshape(-1,3)-rim.mean(0),axis=1).min(),'farthest',np.linalg.norm(tri.reshape(-1,3)-rim.mean(0),axis=1).max())
for x in [rim.mean(0),rim.mean(0)+[-.5,0,0],rim.mean(0)+[-1,0,0],rim.mean(0)+[-1.5,0,0],rim.mean(0)+[0,0,.5],rim.mean(0)+[0,0,1]]:print('probe',x,sd.EvaluateFunction(x))
